      },
      "Next": "UpsertDynamoDB"
    },
    "UpsertDynamoDB": {
      "Type": "Task",
      "Resource": "arn:aws:states:::dynamodb:putItem",
      "Parameters": {
        "TableName": "ChatIndex",
        "Item": {
